/* @catalog — generated by `npm run catalog:generate`; do not edit by hand.
 * Internal
 *   Functions: member, picked, skipped
 *   Constants: guard
 * Tests
 *   - the weight thresholds are four to be picked and eight to be searched alone
 *   - every generic title is skipped in all four languages, also with a trailing number, and the list is published in the workbench documentation
 *   - titles of only digits and punctuation are skipped
 *   - an instrumental, off-vocal or karaoke version is skipped, never reduced, even behind a featuring note
 *   - each trailing note kind is removed, at most three in a row, and a segment without a note ends the peeling
 *   - a title and its noted version give one entry, the earlier in Album order, and a title repeated in another case is skipped for both members
 *   - a title equal to the Album title or the submitted text is skipped, also with a note on either side
 *   - file-name-shaped titles are skipped, while a title with digits that reads as a name is kept
 *   - weights count Han, kana and Hangul twice and other letters and digits once, a title below four is skipped, and heavier titles rank first
 *   - the whole ranked list comes back, never capped, with each member's own Artist name as given
 *   - an empty Album gives no title, and malformed or unsendable members never throw and give none
 * @end-catalog */

/**
 * The pure picker of an existing Album's distinctive saved Track titles (lookupTrackTitles.ts): generic, version-marked,
 * file-name-shaped, repeated and light titles skipped, trailing notes removed, weights and the ranked order, and totality on
 * malformed members. Titles are synthetic or common song-title shapes; no network.
 */
import assert from 'node:assert/strict';
import { readFileSync } from 'node:fs';
import { after, test } from 'node:test';
import {
    distinctiveTrackTitles, GENERIC_TRACK_TITLES, TRACK_TITLE_MIN_WEIGHT, trackTitleText, trackTitleWeight, UNCREDITED_TRACK_TITLE_MIN_WEIGHT
} from '../../src/administration/lookup/lookupTrackTitles';
import { installNetworkGuard } from '../support/networkGuard';

const guard = installNetworkGuard();
after(() => { guard.restore(); assert.deepEqual(guard.attempts, []); });

/** One member with a saved title, an optional retained filename and its own Artist name. */
const member = (title: unknown, originalFileName: unknown = null, artist: string | null = null) => ({ title, originalFileName, artist });
/** The texts picked from these titles, in ranked order, for an Album titled `album`. */
const picked = (titles: unknown[], album: unknown = 'Synthetic Album', submittedText?: unknown) =>
    distinctiveTrackTitles(titles.map(title => member(title)), { albumTitle: album, submittedText }).map(entry => entry.text);
/** Whether a title alone, beside a distinctive one, is skipped. */
const skipped = (title: unknown, originalFileName: unknown = null) =>
    !distinctiveTrackTitles([member(title, originalFileName), member('Synthetic Anchor Title')], { albumTitle: 'Synthetic Album' }).some(entry => entry.text !== 'Synthetic Anchor Title');

test('the weight thresholds are four to be picked and eight to be searched alone', () => {
    assert.deepEqual([TRACK_TITLE_MIN_WEIGHT, UNCREDITED_TRACK_TITLE_MIN_WEIGHT], [4, 8]);
});

test('every generic title is skipped in all four languages, also with a trailing number, and the list is published in the workbench documentation', () => {
    assert.ok(GENERIC_TRACK_TITLES.length >= 40);
    assert.ok(Object.isFrozen(GENERIC_TRACK_TITLES));
    for (const title of GENERIC_TRACK_TITLES) {
        assert.equal(skipped(title), true, title);
        assert.equal(skipped(title.toUpperCase()), true, title);
        assert.equal(skipped(`${title} 2`), true, `${title} 2`);
    }
    for (const title of ['Interlude 2', 'Track01', 'トラック3', 'Untitled Track', 'Bonus Track 12', 'INTRO', 'Intro.', '前奏 1', '인트로2', 'Ｉｎｔｒｏ']) assert.equal(skipped(title), true, title);
    // A generic word inside a longer title is no generic title.
    for (const title of ['Intro to Synthetic Love', 'Track of the Synthetic Night']) assert.equal(skipped(title), false, title);
    const documentation = readFileSync(new URL('../../docs/features/admin-workbench.md', import.meta.url), 'utf8');
    for (const title of GENERIC_TRACK_TITLES) assert.ok(documentation.includes(title), `admin-workbench.md lists ${title}`);
});

test('titles of only digits and punctuation are skipped', () => {
    for (const title of ['01', '2020', 'Ⅳ', '--', '!!!', '１２', '3.14', '♪', ' ']) assert.equal(skipped(title), true, title);
});

test('an instrumental, off-vocal or karaoke version is skipped, never reduced, even behind a featuring note', () => {
    for (const title of ['Synthetic Song (Instrumental)', 'Synthetic Song - Off Vocal', 'Synthetic Song (Inst.)', 'Synthetic Song (MR)', 'Synthetic Song (伴奏)',
        'Synthetic Song（纯音乐）', 'Synthetic Song【カラオケ】', 'Synthetic Song (Instrumental Version)', 'Synthetic Song (Instrumental) (feat. Synthetic Guest)',
        'Synthetic Song [Off-Vocal]', 'Synthetic Song - Backing Track', 'Synthetic Song (オフボーカル)', 'Synthetic Song (반주)', 'Synthetic Song - インスト',
        'Synthetic Song （Ｉｎｓｔ．）', 'Synthetic Song (Karaoke Ver.)', 'Synthetic Song (MR ver.)', 'Synthetic Song - MR', 'Synthetic Song (ＭＲ)']) {
        assert.equal(skipped(title), true, title);
    }
    // A version word in the title itself, not a trailing segment, marks nothing.
    assert.deepEqual(picked(['Instrumental Synthetic Dreams']), ['Instrumental Synthetic Dreams']);
    // `MR` marks only in upper case and not followed by a period, so a name such as `Mr. Monkey` or `Mr.Children` marks nothing.
    assert.deepEqual(picked(['Hello (Mr. Monkey)']), ['Hello (Mr. Monkey)']);
    assert.deepEqual(picked(['Song Title (feat. Mr.Children)']), ['Song Title']);
    assert.deepEqual(picked(['Synthetic Song - Mr. Big Tribute']), ['Synthetic Song - Mr. Big Tribute']);
    for (const title of ['Synthetic Song (M.R.)', 'Synthetic Song (MRS)', 'Synthetic Song (Mr)']) assert.equal(skipped(title), false, title);
});

test('each trailing note kind is removed, at most three in a row, and a segment without a note ends the peeling', () => {
    for (const title of ['Synthetic Song (feat. Synthetic Guest)', 'Synthetic Song - ft. Synthetic Guest', 'Synthetic Song (featuring Synthetic Guest)',
        'Synthetic Song (2011 Remaster)', 'Synthetic Song [Remastered]', 'Synthetic Song - Live at Budokan', 'Synthetic Song (Album Version)',
        'Synthetic Song (Radio Edit)', 'Synthetic Song (Extended Mix)', 'Synthetic Song (Mono)', 'Synthetic Song (Acoustic)', 'Synthetic Song – Stereo Remix',
        'Synthetic Song — Remastered 2009', 'Synthetic Song（Live）', 'Synthetic Song【Remix】', 'Synthetic Song (Live) [2011 Remaster]',
        'Synthetic Song (Live) (Mono) (Remix)']) {
        assert.equal(trackTitleText(title), 'Synthetic Song', title);
    }
    // A fourth trailing note stays; a segment without a note (or with nothing before it) stops the peeling.
    assert.equal(trackTitleText('Synthetic Song (Live) (Mono) (Remix) (Edit)'), 'Synthetic Song (Live)');
    assert.equal(trackTitleText('Synthetic Song (Part 1) (Live)'), 'Synthetic Song (Part 1)');
    assert.equal(trackTitleText('Synthetic Song - Part 2'), 'Synthetic Song - Part 2');
    assert.equal(trackTitleText('(Live)'), '(Live)');
    assert.equal(trackTitleText('Synthetic Song (Part (Live))'), 'Synthetic Song (Part (Live))');
    // Notes are words: "Delivery" and "Oliver" hold none.
    assert.equal(trackTitleText('Synthetic Song (Delivery)'), 'Synthetic Song (Delivery)');
    assert.equal(trackTitleText('Synthetic Song - Oliver'), 'Synthetic Song - Oliver');
    assert.equal(trackTitleText(7), null);
    assert.equal(trackTitleText('   '), null);
});

test('a title and its noted version give one entry, the earlier in Album order, and a title repeated in another case is skipped for both members', () => {
    assert.deepEqual(picked(['Synthetic Song', 'Synthetic Song (Live)']), ['Synthetic Song']);
    assert.deepEqual(picked(['Synthetic Song (Live)', 'Synthetic Song']), ['Synthetic Song']);
    assert.deepEqual(distinctiveTrackTitles([member('Synthetic Song (Live)', null, 'Synthetic Live Band'), member('Synthetic Song', null, 'Synthetic Band')], { albumTitle: null }),
        [{ text: 'Synthetic Song', artist: 'Synthetic Live Band', weight: 13 }]);
    assert.deepEqual(picked(['Love Synthetic Song', 'love synthetic song', 'Other Synthetic Song']), ['Other Synthetic Song']);
    assert.deepEqual(picked(['Love Synthetic Song', 'LOVE SYNTHETIC SONG!', 'Other Synthetic Song']), ['Other Synthetic Song']);
});

test('a title equal to the Album title or the submitted text is skipped, also with a note on either side', () => {
    assert.deepEqual(picked(['Synthetic Album', 'Synthetic Album (Live)', 'Other Synthetic Song'], 'Synthetic Album'), ['Other Synthetic Song']);
    assert.deepEqual(picked(['Synthetic Album', 'Other Synthetic Song'], 'Synthetic Album (2013 Remaster)'), ['Other Synthetic Song']);
    assert.deepEqual(picked(['Typed Synthetic Song', 'Typed Synthetic Song (feat. Synthetic Guest)', 'Other Synthetic Song'], 'Synthetic Album', 'typed synthetic song [Remix]'),
        ['Other Synthetic Song']);
    // An Album title or submitted text that does not clean excludes nothing.
    assert.deepEqual(picked(['Other Synthetic Song'], null, 7), ['Other Synthetic Song']);
});

test('file-name-shaped titles are skipped, while a title with digits that reads as a name is kept', () => {
    for (const title of ['01 - Synthetic Song', '1. Synthetic Song', '03_synthetic_song', '03_song', 'REC_0001', 'song.mp3', 'Synthetic Song.FLAC', '12) Synthetic Song']) {
        assert.equal(skipped(title), true, title);
    }
    // The member's retained original filename, with or without its extension, ignoring case.
    assert.equal(skipped('Synthetic Take Seven', 'synthetic take seven.wav'), true);
    assert.equal(skipped('Synthetic Take Seven.wav', 'Synthetic Take Seven.wav'), true);
    assert.equal(skipped('Synthetic Take Seven', 'Synthetic Take Eight.wav'), false);
    assert.equal(skipped('Synthetic Take Seven', 7), false);
    // Digits alone never make a title file-name-shaped, even a one-word ASCII title with a run of them, nor does an underscore at an end.
    for (const title of ['東京2020', '99 Problems', 'Synthetic 1999 Party', '1000 Synthetic Nights', 'REC0001', 'Room404', 'Blink182', 'B612', 'synthetic.track.0042',
        '_Synthetic', 'Synthetic1_', '__Synthetic__']) {
        assert.equal(skipped(title), false, title);
    }
});

test('weights count Han, kana and Hangul twice and other letters and digits once, a title below four is skipped, and heavier titles rank first', () => {
    assert.deepEqual([trackTitleWeight('A-1'), trackTitleWeight('さくら'), trackTitleWeight('東京夜景'), trackTitleWeight('Seventh'), trackTitleWeight(' -!, ·'),
        trackTitleWeight('사랑해'), trackTitleWeight('Café'), trackTitleWeight('e\u0301'), trackTitleWeight(null)], [2, 6, 8, 7, 0, 6, 4, 1, 0]);
    // A letter those scripts share counts two as well (the prolonged sound mark, also half-width, and the iteration marks), while
    // their punctuation counts nothing.
    assert.deepEqual([trackTitleWeight('コーヒー'), trackTitleWeight('ﾗｰﾒﾝ'), trackTitleWeight('時々'), trackTitleWeight('〇'), trackTitleWeight('、。〜・')], [8, 8, 4, 2, 0]);
    assert.deepEqual(distinctiveTrackTitles([member('コーヒー')], { albumTitle: null }).map(entry => entry.weight), [UNCREDITED_TRACK_TITLE_MIN_WEIGHT]);
    assert.equal(skipped('A-1'), true);
    assert.equal(skipped('Abc'), true);
    assert.deepEqual(picked(['さくら']), ['さくら']);
    // A four-character Japanese title (8) ranks before a seven-letter English one (7); ties keep Album order.
    assert.deepEqual(picked(['Seventh', '東京夜景', 'Eleventh', 'Twelfths']), ['東京夜景', 'Eleventh', 'Twelfths', 'Seventh']);
    // The weight is that of the text without notes.
    assert.deepEqual(distinctiveTrackTitles([member('Abc (feat. Synthetic Guest Ensemble)')], { albumTitle: null }), []);
});

test('the whole ranked list comes back, never capped, with each member\'s own Artist name as given', () => {
    const titles = ['First Synthetic Song', 'Second Synthetic Song', 'Third Synthetic Song', 'Fourth Synthetic Song', 'Fifth Synthetic Song'];
    const entries = distinctiveTrackTitles(titles.map((title, index) => member(title, `${index + 1}.flac`, index % 2 ? `Synthetic Artist ${index}` : null)), { albumTitle: 'Synthetic Album' });
    assert.deepEqual(entries.map(entry => [entry.text, entry.artist, entry.weight]), [
        ['Second Synthetic Song', 'Synthetic Artist 1', 19], ['Fourth Synthetic Song', 'Synthetic Artist 3', 19], ['First Synthetic Song', null, 18],
        ['Third Synthetic Song', null, 18], ['Fifth Synthetic Song', null, 18]]);
});

test('an empty Album gives no title, and malformed or unsendable members never throw and give none', () => {
    assert.deepEqual(distinctiveTrackTitles([], { albumTitle: 'Synthetic Album' }), []);
    assert.deepEqual(distinctiveTrackTitles(null as never, { albumTitle: 'Synthetic Album' }), []);
    const members = [null, 7, 'x', [], { title: 7 }, { title: null }, { title: 'x'.repeat(201) }, { title: 'x '.repeat(500) }, { title: 'https://example.test/song' },
        { title: 'www.example.test' }, { title: 'Synthetic \ud800 Song' }, { title: 'Valid Synthetic Song', originalFileName: { name: 'x' }, artist: 7 },
        { title: 'Synthetic\u200b Song\u0007 Title', artist: 'Synthetic Band' }];
    assert.deepEqual(distinctiveTrackTitles(members, { albumTitle: { title: 'x' } as never, submittedText: ['x'] as never }), [
        { text: 'Valid Synthetic Song', artist: null, weight: 18 }, { text: 'Synthetic Song Title', artist: 'Synthetic Band', weight: 18 }]);
});
